$ErrorActionPreference = 'Stop'
$repo = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$r4 = Join-Path $repo 'R4_CROSS_DOMAIN_VALIDATION'
$qa = Join-Path $r4 '03_extraction\qa'
$repair = Join-Path $qa 'repair'
New-Item -ItemType Directory -Force -Path $repair | Out-Null

$workingPath = Join-Path $qa 'human_review\R4_2B_HUMAN_REVIEW_WORKING.csv'
$queuePath = Join-Path $qa 'R4_2C_TARGETED_HUMAN_REVIEW_QUEUE_V2.csv'
$comparisonPath = Join-Path $qa 'R4_2C_LUNA_SELFREVIEW_TERRA_COMPARISON.csv'
$terraPath = Join-Path $qa 'R4_2C_TERRA_INDEPENDENT_CALIBRATED_REVIEW_V2.csv'
$samplePath = Join-Path $repair 'R4_2D_CROSS_MODEL_DIAGNOSTIC_SAMPLE.csv'
$panelPath = Join-Path $repair 'R4_2D_HUMAN_DIAGNOSTIC_PANEL.html'
$logPath = Join-Path $r4 'R4_AI_EXECUTION_LOG.csv'
foreach($p in @($workingPath,$queuePath,$comparisonPath,$terraPath,$logPath)){if(-not(Test-Path -LiteralPath $p)){throw "Required source missing: $p"}}

function Hash-File([string]$Path){(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash}
$immutablePaths=@(
 (Join-Path $r4 '03_extraction\R4_STRUCTURAL_EXTRACTION.csv'),
 (Join-Path $qa 'R4_2B_HUMAN_CALIBRATION_SEED_V1.csv'),
 (Join-Path $qa 'R4_2C_TERRA_INDEPENDENT_CALIBRATED_REVIEW_V2.csv'),
 (Join-Path $qa 'R4_2C_LUNA_SELFREVIEW_TERRA_COMPARISON.csv'),
 (Join-Path $qa 'R4_2C_TARGETED_HUMAN_REVIEW_QUEUE_V2.csv')
)
$before=@{};foreach($p in $immutablePaths){$before[$p]=Hash-File $p}

$selection=@(
 [pscustomobject]@{QA_ID='QA2B-009';PATTERN='COUNTERPART_RECIPIENT_OVERATTRIBUTION';SELECTION_TYPE='TYPICAL';REASON='GDPR operative article; direct legal action with a concise contextual “to the risk” phrase in both role slots; Terra did not abstain.'}
 [pscustomobject]@{QA_ID='QA2B-026';PATTERN='COUNTERPART_RECIPIENT_OVERATTRIBUTION';SELECTION_TYPE='COMPLEX';REASON='GDPR recital with multiple Commission propositions, long cross-clause structure, LOW confidence and Terra abstention.'}
 [pscustomobject]@{QA_ID='QA2B-036';PATTERN='COUNTERPART_RECIPIENT_OVERATTRIBUTION';SELECTION_TYPE='TYPICAL';REASON='DSA operative article; clear action with a rights/interests complement duplicated into both role slots; Terra did not abstain.'}
 [pscustomobject]@{QA_ID='QA2B-056';PATTERN='COUNTERPART_RECIPIENT_OVERATTRIBUTION';SELECTION_TYPE='COMPLEX';REASON='DSA recital involving multiple advertising actors, an invitation relation, LOW confidence and Terra abstention.'}
 [pscustomobject]@{QA_ID='QA2B-067';PATTERN='COUNTERPART_RECIPIENT_OVERATTRIBUTION';SELECTION_TYPE='TYPICAL';REASON='AI Act operative article; short mandate/source phrase duplicated into counterpart and recipient; Terra did not abstain.'}
 [pscustomobject]@{QA_ID='QA2B-089';PATTERN='COUNTERPART_RECIPIENT_OVERATTRIBUTION';SELECTION_TYPE='COMPLEX';REASON='AI Act annex procedure with multiple actors, long nested clauses, LOW confidence and Terra abstention.'}
 [pscustomobject]@{QA_ID='QA2B-010';PATTERN='ACTOR_ACTION_FRAGMENTATION';SELECTION_TYPE='TYPICAL';REASON='GDPR operative article; single clear consultation action and procedural object.'}
 [pscustomobject]@{QA_ID='QA2B-025';PATTERN='ACTOR_ACTION_FRAGMENTATION';SELECTION_TYPE='COMPLEX';REASON='GDPR recital with several clauses, a consequence followed by a Member State proposition, LOW confidence and Terra abstention.'}
 [pscustomobject]@{QA_ID='QA2B-033';PATTERN='ACTOR_ACTION_FRAGMENTATION';SELECTION_TYPE='TYPICAL';REASON='DSA operative article; compact notification action where the extracted action is reduced to “also”.'}
 [pscustomobject]@{QA_ID='QA2B-054';PATTERN='ACTOR_ACTION_FRAGMENTATION';SELECTION_TYPE='COMPLEX';REASON='DSA recital with long subordinate clauses and multiple distinct actors/actions, LOW confidence and Terra abstention.'}
 [pscustomobject]@{QA_ID='QA2B-077';PATTERN='ACTOR_ACTION_FRAGMENTATION';SELECTION_TYPE='TYPICAL';REASON='AI Act operative article; explicit list of possible actors and a short legal consequence, suitable for actor/action boundary inspection.'}
 [pscustomobject]@{QA_ID='QA2B-083';PATTERN='ACTOR_ACTION_FRAGMENTATION';SELECTION_TYPE='COMPLEX';REASON='AI Act recital with extended multi-sentence reasoning and cross-reference, LOW confidence and Terra abstention.'}
)
$work=@(Import-Csv -LiteralPath $workingPath);$queue=@(Import-Csv -LiteralPath $queuePath);$comparison=@(Import-Csv -LiteralPath $comparisonPath);$terra=@(Import-Csv -LiteralPath $terraPath)
$workBy=@{};foreach($r in $work){$workBy[$r.QA_ID]=$r};$qBy=@{};foreach($r in $queue){$qBy[$r.QA_ID]=$r};$cBy=@{};foreach($r in $comparison){$cBy[$r.QA_ID]=$r};$tBy=@{};foreach($r in $terra){$tBy[$r.QA_ID]=$r}
$celex=@{D1_GDPR='32016R0679';D2_DSA='32022R2065';D3_AI_ACT='32024R1689'}
$out=foreach($pick in $selection){
 if(-not $workBy.ContainsKey($pick.QA_ID) -or -not $qBy.ContainsKey($pick.QA_ID) -or -not $cBy.ContainsKey($pick.QA_ID) -or -not $tBy.ContainsKey($pick.QA_ID)){throw "Selected ID lacks source or priority evidence: $($pick.QA_ID)"}
 $s=$workBy[$pick.QA_ID];$q=$qBy[$pick.QA_ID];$c=$cBy[$pick.QA_ID];$t=$tBy[$pick.QA_ID]
 if($q.PRIORITY -ne 'PRIORITY_1_CROSS_MODEL_ERROR'){throw "Selected record is not Priority 1: $($pick.QA_ID)"}
 if([string]::IsNullOrWhiteSpace($s.FULL_SOURCE_TEXT) -or $s.SOURCE_RESOLUTION_STATUS -notlike 'RESOLVED*'){throw "Full frozen source unresolved: $($pick.QA_ID)"}
 $base=[ordered]@{DIAGNOSTIC_ID=('R4_2D-'+$pick.QA_ID);QA_ID=$pick.QA_ID;EXTRACTION_ID=$s.EXTRACTION_ID;CASE_ID=$s.CASE_ID;CELEX=$celex[$s.CASE_ID];SOURCE_POINTER=$s.SOURCE_POINTER;SOURCE_TYPE=$s.SOURCE_TYPE;PATTERN=$pick.PATTERN;SELECTION_TYPE=$pick.SELECTION_TYPE;SELECTION_REASON=$pick.REASON;PRIORITY=$q.PRIORITY;LUNA_ACTOR=$s.ACTOR_TEXT_LUNA;LUNA_ACTION=$s.LEGAL_ACTION_LUNA;LUNA_OBJECT=$s.ACTION_OBJECT_LUNA;LUNA_COUNTERPART=$s.COUNTERPART_LUNA;LUNA_RECIPIENT=$s.RECIPIENT_LUNA;LUNA_SELFREVIEW_ERROR=$c.LUNA_SELFREVIEW_ERROR_TYPES;TERRA_ERROR=$t.ERROR_TYPE_TERRA;TERRA_CORRECTION=$t.CORRECTION_PROPOSED_TERRA;TERRA_CONFIDENCE=$t.TERRA_DECISION_CONFIDENCE;TERRA_ABSTAIN=$t.TERRA_ABSTAIN;FULL_SOURCE_TEXT=$s.FULL_SOURCE_TEXT;FULL_SOURCE_CONTEXT_BEFORE=$s.FULL_SOURCE_CONTEXT_BEFORE;FULL_SOURCE_CONTEXT_AFTER=$s.FULL_SOURCE_CONTEXT_AFTER;HUMAN_PATTERN_CONFIRMED='';HUMAN_ACTOR_CORRECT='';HUMAN_ACTION_CORRECT='';HUMAN_OBJECT_CORRECT='';HUMAN_COUNTERPART_CORRECT='';HUMAN_RECIPIENT_CORRECT='';HUMAN_CORRECT_ACTOR='';HUMAN_CORRECT_ACTION='';HUMAN_CORRECT_OBJECT='';HUMAN_CORRECT_COUNTERPART='';HUMAN_CORRECT_RECIPIENT='';HUMAN_NOTES='';HUMAN_REVIEWER='';HUMAN_REVIEW_STATUS=''}
 [pscustomobject]$base
}
if($out.Count -ne 12){throw "Expected 12 diagnostic cases; found $($out.Count)."}
if(@($out.QA_ID|Select-Object -Unique).Count -ne 12){throw 'Sample IDs are not unique.'}
foreach($case in $celex.Keys){$n=@($out|Where-Object CASE_ID -eq $case).Count;if($n -ne 4){throw "Expected four records for $case; found $n."}}
foreach($pattern in 'COUNTERPART_RECIPIENT_OVERATTRIBUTION','ACTOR_ACTION_FRAGMENTATION'){foreach($case in $celex.Keys){$n=@($out|Where-Object {$_.CASE_ID -eq $case -and $_.PATTERN -eq $pattern}).Count;if($n -ne 2){throw "Expected two $pattern records for $case; found $n."}}}
$out|Export-Csv -NoTypeInformation -Encoding UTF8 -LiteralPath $samplePath

$json=ConvertTo-Json -InputObject @($out) -Depth 6 -Compress
$json=$json -replace '&','\u0026' -replace '<','\u003c' -replace '>','\u003e'
$html=@'
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>R4.2D Human Diagnostic</title>
<style>
:root{--ink:#1b2838;--muted:#627084;--line:#d9e0e8;--blue:#1c5b91;--paper:#fff;--bg:#f3f6f9;--amber:#fff5d8;--green:#eaf8ef}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,Segoe UI,sans-serif}header{position:sticky;top:0;z-index:5;background:#183852;color:white;padding:15px 22px}h1{font-size:20px;margin:0}.firewall{background:#fff0e7;border:1px solid #e8b59a;color:#81371c;padding:9px 12px;margin:9px 0 0;border-radius:7px;font-weight:700}.bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:10px}.bar button,button{border:1px solid var(--line);border-radius:6px;background:#fff;color:var(--ink);padding:8px 11px;cursor:pointer;font:inherit}.bar .primary{background:#2673ad;border-color:#2673ad;color:#fff}.count{margin-left:auto;font-weight:700}.wrap{max-width:1300px;margin:auto;padding:18px}.meta{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:8px;margin-bottom:12px}.box,.panel{border:1px solid var(--line);background:var(--paper);border-radius:8px;padding:13px;margin-bottom:12px}.source{background:#eff7ff;border-color:#b5cee5}.model{background:var(--amber);border-color:#e8d69a}.source-text{white-space:pre-wrap;max-height:56vh;overflow:auto;font:13px/1.55 ui-monospace,Consolas,monospace}.label{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.value{font-weight:650;white-space:pre-wrap;overflow-wrap:anywhere}.extract{display:grid;grid-template-columns:145px 1fr;gap:8px;padding:7px 0;border-bottom:1px solid #edf0f3}.extract:last-child{border-bottom:0}.tag{display:inline-block;border:1px solid #d6dee7;border-radius:99px;padding:3px 8px;background:#f7f9fb;font-size:12px;font-weight:700}.model-tag{background:#feecc1;border-color:#edcf79;color:#765613;font-weight:800}.form{background:var(--green);border-color:#b6dcc2}.question{display:grid;grid-template-columns:minmax(230px,1fr) 180px;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid #e0ece4}.question:last-of-type{border:0}.question select,.question textarea,input{font:inherit;border:1px solid #ccd6df;border-radius:6px;padding:8px;background:white}.corrections{display:grid;grid-template-columns:repeat(2,minmax(220px,1fr));gap:9px}.corrections label{font-size:12px;color:var(--muted)}.corrections input{width:100%;display:block;margin-top:4px}.notes{width:100%;min-height:80px;resize:vertical}.nav{display:flex;gap:8px;align-items:center;margin:10px 0}.status{font-weight:700;color:var(--blue)}.muted{color:var(--muted);font-size:13px}@media(max-width:750px){.meta{grid-template-columns:repeat(2,1fr)}.question{grid-template-columns:1fr}.corrections{grid-template-columns:1fr}.count{margin-left:0}.wrap{padding:10px}}
</style></head><body>
<header><h1>R4.2D — Human diagnostic of cross-model-supported defects</h1><div class="firewall">STRUCTURAL EXTRACTION ONLY. R/I/T CODING NOT STARTED. MECHANISM CODING NOT STARTED. ROTEM NOT CONSULTED.</div><div class="bar"><button id="prev">Previous</button><button id="next" class="primary">Next</button><label>Go to <select id="goto"></select></label><button id="save">Save locally</button><button id="csv">Export completed CSV</button><button id="json">Export JSON</button><span class="count" id="count"></span></div></header>
<main class="wrap"><div id="app"></div><div class="nav"><button id="prev2">Previous</button><button id="next2" class="primary">Next</button><span class="status" id="saved"></span></div></main>
<script>
const rows=__ROWS__;const key='R4_2D_HUMAN_DIAGNOSTIC_V1';let i=0;const explicit=['HUMAN_PATTERN_CONFIRMED','HUMAN_ACTOR_CORRECT','HUMAN_ACTION_CORRECT','HUMAN_OBJECT_CORRECT','HUMAN_COUNTERPART_CORRECT','HUMAN_RECIPIENT_CORRECT'];const opts=(values,current)=>'<option value="">Select…</option>'+values.map(v=>'<option '+(current===v?'selected':'')+'>'+v+'</option>').join('');const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function isDone(r){return explicit.every(k=>['YES','NO','N/A','PARTIALLY'].includes(r[k]))&&['YES','PARTIALLY','NO'].includes(r.HUMAN_PATTERN_CONFIRMED)}function saveState(){localStorage.setItem(key,JSON.stringify(rows));document.getElementById('saved').textContent='Saved locally';renderCount()}function loadState(){try{const old=JSON.parse(localStorage.getItem(key)||'null');if(Array.isArray(old)&&old.length===rows.length&&old.every((x,n)=>x.QA_ID===rows[n].QA_ID))for(let n=0;n<rows.length;n++)Object.assign(rows[n],old[n])}catch{}}
function renderCount(){let done=rows.filter(isDone).length;document.getElementById('count').textContent='Reviewed '+done+' / 12'}function sourceBlock(r){return '<section class="box source"><div class="label">A. Frozen legal source — '+esc(r.SOURCE_TYPE)+' · '+esc(r.SOURCE_POINTER)+'</div><h2>'+esc(r.CELEX)+'</h2>'+(r.FULL_SOURCE_CONTEXT_BEFORE?'<details><summary>Adjacent context before</summary><div class="source-text">'+esc(r.FULL_SOURCE_CONTEXT_BEFORE)+'</div></details>':'')+'<div class="source-text">'+esc(r.FULL_SOURCE_TEXT)+'</div>'+(r.FULL_SOURCE_CONTEXT_AFTER?'<details><summary>Adjacent context after</summary><div class="source-text">'+esc(r.FULL_SOURCE_CONTEXT_AFTER)+'</div></details>':'')+'</section>'}
function render(){let r=rows[i];document.getElementById('goto').innerHTML=rows.map((x,n)=>'<option value="'+n+'" '+(i===n?'selected':'')+'>'+esc(x.DIAGNOSTIC_ID)+' · '+esc(x.PATTERN.replaceAll('_',' '))+'</option>').join('');document.getElementById('app').innerHTML='<div class="meta"><div class="box"><div class="label">Diagnostic ID</div><div class="value">'+esc(r.DIAGNOSTIC_ID)+'</div></div><div class="box"><div class="label">Act / source</div><div class="value">'+esc(r.CASE_ID)+' · '+esc(r.SOURCE_TYPE)+'</div></div><div class="box"><div class="label">Pattern</div><div class="value">'+esc(r.PATTERN)+'</div></div><div class="box"><div class="label">Selection</div><div class="value">'+esc(r.SELECTION_TYPE)+': '+esc(r.SELECTION_REASON)+'</div></div></div>'+sourceBlock(r)+'<section class="box"><div class="label">B. Original Luna extraction</div>'+[['Actor','LUNA_ACTOR'],['Action','LUNA_ACTION'],['Object','LUNA_OBJECT'],['Counterpart','LUNA_COUNTERPART'],['Recipient','LUNA_RECIPIENT']].map(([l,k])=>'<div class="extract"><strong>'+l+'</strong><div class="value">'+(r[k]?esc(r[k]):'<em>None stored</em>')+'</div></div>').join('')+'</section><section class="box model"><span class="tag model-tag">MODEL DIAGNOSTIC — NOT HUMAN GROUND TRUTH</span><div class="extract"><strong>Luna self-review detected</strong><div class="value">'+(r.LUNA_SELFREVIEW_ERROR?esc(r.LUNA_SELFREVIEW_ERROR):'No error listed')+'</div></div><div class="extract"><strong>Terra independent review detected</strong><div class="value">'+(r.TERRA_ERROR?esc(r.TERRA_ERROR):'No error listed')+' · confidence '+esc(r.TERRA_CONFIDENCE)+' · abstain '+esc(r.TERRA_ABSTAIN)+'</div></div><div class="extract"><strong>Terra proposed correction</strong><div class="value">'+(r.TERRA_CORRECTION?esc(r.TERRA_CORRECTION):'None recorded')+'</div></div></section><section class="box form"><div class="label">D. Researcher decision — '+esc(r.HUMAN_REVIEWER||'Igor Caires Machado')+'</div><h2>Is the cross-model-supported defect actually present in this record?</h2><div class="question"><label>Human pattern confirmation</label><select data-key="HUMAN_PATTERN_CONFIRMED">'+opts(['YES','NO','PARTIALLY'],r.HUMAN_PATTERN_CONFIRMED)+'</select></div>'+[['HUMAN_ACTOR_CORRECT','Actor correct?'],['HUMAN_ACTION_CORRECT','Action correct?'],['HUMAN_OBJECT_CORRECT','Object correct?'],['HUMAN_COUNTERPART_CORRECT','Counterpart correct?'],['HUMAN_RECIPIENT_CORRECT','Recipient correct?']].map(([k,l])=>'<div class="question"><label>'+l+'</label><select data-key="'+k+'">'+opts(['YES','NO','N/A'],r[k])+'</select></div>').join('')+'<h3>Concise corrections, where needed</h3><div class="corrections">'+[['HUMAN_CORRECT_ACTOR','Correct actor'],['HUMAN_CORRECT_ACTION','Correct action'],['HUMAN_CORRECT_OBJECT','Correct object'],['HUMAN_CORRECT_COUNTERPART','Correct counterpart'],['HUMAN_CORRECT_RECIPIENT','Correct recipient']].map(([k,l])=>'<label>'+l+'<input data-key="'+k+'" value="'+esc(r[k])+'"></label>').join('')+'</div><h3>Researcher notes</h3><textarea class="notes" data-key="HUMAN_NOTES" placeholder="Optional short rationale or source clarification">'+esc(r.HUMAN_NOTES)+'</textarea><p class="muted">A record is marked REVIEWED only after the primary decision and all five field decisions are explicitly selected. Reviewer name alone never completes a record.</p><button id="saveRecord" class="primary">Save this decision</button><span class="status"> '+esc(r.HUMAN_REVIEW_STATUS||'PENDING')+'</span></section>';
document.querySelectorAll('[data-key]').forEach(el=>{const change=()=>{r[el.dataset.key]=el.value;r.HUMAN_REVIEWER='Igor Caires Machado';r.HUMAN_REVIEW_STATUS='IN_PROGRESS';saveState()};el.addEventListener('input',change);el.addEventListener('change',change)});document.getElementById('saveRecord').onclick=()=>{if(!isDone(r)){r.HUMAN_REVIEW_STATUS='IN_PROGRESS';alert('Complete the primary choice and all five field decisions before marking REVIEWED.')}else{r.HUMAN_REVIEWER='Igor Caires Machado';r.HUMAN_REVIEW_STATUS='REVIEWED'}saveState();render()};renderCount()}
function nav(d){i=Math.max(0,Math.min(rows.length-1,i+d));render()}function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function csv(){const cols=Object.keys(rows[0]);const q=x=>'"'+String(x??'').replace(/"/g,'""')+'"';return [cols.map(q).join(','),...rows.map(r=>cols.map(k=>q(r[k])).join(','))].join('\r\n')}
document.getElementById('prev').onclick=document.getElementById('prev2').onclick=()=>nav(-1);document.getElementById('next').onclick=document.getElementById('next2').onclick=()=>nav(1);document.getElementById('goto').onchange=e=>{i=Number(e.target.value);render()};document.getElementById('save').onclick=saveState;document.getElementById('csv').onclick=()=>download('R4_2D_HUMAN_DIAGNOSTIC_COMPLETED.csv',csv(),'text/csv;charset=utf-8');document.getElementById('json').onclick=()=>download('R4_2D_HUMAN_DIAGNOSTIC_COMPLETED.json',JSON.stringify(rows,null,2),'application/json;charset=utf-8');loadState();render();
</script></body></html>
'@
$html=$html.Replace('__ROWS__',$json)
[System.IO.File]::WriteAllText($panelPath,$html,(New-Object System.Text.UTF8Encoding($false)))

$readme=@'
# R4.2D Human diagnostic

Open `R4_2D_HUMAN_DIAGNOSTIC_PANEL.html` locally in a modern browser. The panel has no external resources. It presents one case at a time: frozen full legal text, original Luna fields, then labeled Luna/Terra diagnostic evidence, followed by researcher decisions.

Review the source text directly. `NONE_EXPLICIT` is permitted for counterpart and recipient when the provision expresses neither relation. For passive structures, do not invent an actor; `ACTOR_NOT_EXPLICIT` may be entered in the correction field. Do not assign regulator/intermediary/target roles or code mechanisms.

The panel stores answers in browser local storage. It marks a record `REVIEWED` only after a human pattern decision and all five separate field decisions have been selected. Export CSV and JSON after review; preserve both exports.

The 12-row sample uses Priority 1 paired-model cases, with two cases per pattern and act. It is purposive and diagnoses whether the patterns occur; it cannot estimate prevalence in the 1,404-row corpus. No human decisions are prefilled.
'@
[System.IO.File]::WriteAllText((Join-Path $repair 'README_R4_2D_HUMAN_DIAGNOSTIC.md'),$readme,(New-Object System.Text.UTF8Encoding($false)))

# Log interface/sample preparation only. Do not log researcher adjudication as AI execution.
$logs=@(Import-Csv -LiteralPath $logPath|Where-Object RUN_ID -ne 'R4_2D_BUILD_001')
$logs += [pscustomobject]@{RUN_ID='R4_2D_BUILD_001';DATE='2026-09-26';ROUND='R4';PHASE='R4.2D';CASE_ID='ALL';TASK='Build purposive 12-record cross-model human diagnostic sample and local review panel';TASK_TYPE='HUMAN_DIAGNOSTIC_INTERFACE_AND_SAMPLE_CONSTRUCTION';MODEL='Codex runtime; no case adjudication performed';REASONING_LEVEL='HIGH';INPUT_SOURCE='Frozen R4.1 source text; paired V2 comparison; Priority 1 queue; original Luna extraction';PROMPT_VERSION='R4_2D_DIAGNOSTIC_v1';OUTPUT_FILE='03_extraction/qa/repair/R4_2D_CROSS_MODEL_DIAGNOSTIC_SAMPLE.csv; 03_extraction/qa/repair/R4_2D_HUMAN_DIAGNOSTIC_PANEL.html';TASK_COMPLEXITY='MEDIUM';ESCALATED='NO';ESCALATION_REASON='';HUMAN_REVIEW_REQUIRED='YES';HUMAN_REVIEW_STATUS='READY_FOR_RESEARCHER';FINAL_STATUS='R4_2D_DIAGNOSTIC_READY_FOR_RESEARCHER';NOTES='12 records; 4 per act; 6 per pattern; all Priority 1; no human fields prefilled; no legal adjudication, R/I/T, mechanisms or corpus repair.';PHASE_RECLASSIFIED_FROM='';PHASE_RECLASSIFIED_TO='';PHASE_RECLASSIFICATION_REASON=''}
$logs|Export-Csv -NoTypeInformation -Encoding UTF8 -LiteralPath $logPath

$after=@{};foreach($p in $immutablePaths){$after[$p]=Hash-File $p;if($after[$p] -ne $before[$p]){throw "Preservation check failed: $p"}}
Write-Output "R4.2D ready: records=$($out.Count); resolved=$(@($out|Where-Object FULL_SOURCE_TEXT).Count); priority1=$(@($out|Where-Object PRIORITY -eq 'PRIORITY_1_CROSS_MODEL_ERROR').Count); panel=$panelPath"
